/**
 * Land mask for the planetary scene: real coastlines, Natural Earth 110m (world-atlas).
 * 14651 points on a 0.86deg equal-spacing grid, quantised to Int16
 * (lat x180, lon x90) and base64-packed, plus a coastline flag per point
 * (1 = a cardinal neighbour is sea) so shorelines can be drawn brighter.
 * Decoded once on the client.
 */

const PACKED =
  "";

const COAST =
  "";

export const LAND_COUNT = 14651;

/** Returns interleaved [lat, lon, lat, lon, ...] in degrees. */
export function decodeLand(): Float32Array {
  const bin = atob(PACKED);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const q = new Int16Array(bytes.buffer);
  const out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i += 2) {
    out[i] = q[i] / 180;
    out[i + 1] = q[i + 1] / 90;
  }
  return out;
}

/** Returns one byte per point: 1 if the point sits on a coastline. */
export function decodeCoast(): Uint8Array {
  const bin = atob(COAST);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
